import React, { createContext, useState, useEffect } from 'react';
import { Stack } from '../services/contentstack';
import ContentstackLivePreview from '@contentstack/live-preview-utils';

export type ContentstackProviderProps = {
  stack: Stack;
  children: React.ReactNode;
};

type ContentstackContextType = {
  getContent: (contentType: string, entryUid: string, locale?: string) => Promise<any>;
};

export const ContentstackContext = createContext<ContentstackContextType | null>(null);

const ContentstackProvider: React.FC<ContentstackProviderProps> = ({
  stack,
  children,
}) => {
  const [callback, setCallback] = useState<(() => void) | null>(null);

  useEffect(() => {
    const unsubscribe = ContentstackLivePreview.onEntryChange((cb: () => void) => {
      setCallback(() => cb);
    });

    return () => {
      if (unsubscribe) {
        unsubscribe();
      }
    };
  }, []);

  useEffect(() => {
    if (callback) {
      callback();
    }
  }, [callback]);

  const getContent = async (contentType: string, entryUid: string, locale?: string) => {
    return stack.getEntry(contentType, entryUid, locale);
  };

  return (
    <ContentstackContext.Provider value={{ getContent }}>
      {children}
    </ContentstackContext.Provider>
  );
};

export default ContentstackProvider;
